26	fn input_block() -> impl Strategy<Value = (CodeBlock, Vec<String>)> {
27	    (
28	        prop::sample::select(vec!["a.ts", "a.b.ts", "a/z.ts", "b.ts"]),
29	        0usize..4,
30	        0usize..4,
31	        prop::sample::select(KINDS.to_vec()),
32	        prop::sample::select(vec!["", "a()", "b()"]),
33	        prop::collection::vec(0usize..6, 0..3),
34	        prop::collection::vec(prop::sample::select(vec!["user", "name", "foo", "other"]), 0..5),
35	    )
36	        .prop_map(|(file, line_start, line_end, node_kind, code, matched_lines, tokens)| {
37	            let block = CodeBlock {
38	                file: Utf8PathBuf::from(file),
39	                line_start,
40	                line_end,
41	                node_kind,
42	                code: code.to_string(),
43	                symbol_signature: None,
44	                matched_lines,
45	                matched_keywords: Vec::new(),
46	            };
47	            (block, tokens.into_iter().map(String::from).collect())
48	        })
49	}
