51	fn df_strategy() -> impl Strategy<Value = HashMap<String, usize>> {
52	    prop::collection::vec(0usize..8, TERMS.len())
53	        .prop_map(|counts| TERMS.iter().map(ToString::to_string).zip(counts).collect())
54	}
