110	proptest! {
111	    #[test]
112	    fn rank_blocks_matches_the_naive_reference(
113	        blocks in prop::collection::vec(input_block(), 0..12),
114	        terms in terms_strategy(),
115	        df in df_strategy(),
116	    ) {
117	        let ranked = rank_blocks(blocks.clone(), &terms, &df);
118	        prop_assert_eq!(ranked.len(), blocks.len());
119	
120	        // The reference sorts the ranker's own scored blocks; scoring itself is covered by score tests.
121	        let mut input_ids: Vec<_> = blocks.iter().map(|(b, _)| identity(b)).collect();
122	        let mut output_ids: Vec<_> = ranked.iter().map(|r| identity(&r.block)).collect();
123	        input_ids.sort();
124	        output_ids.sort();
125	        prop_assert_eq!(output_ids, input_ids);
126	
127	        let mut scrambled: Vec<RankedBlock> = ranked.iter().rev().cloned().collect();
128	        for r in &mut scrambled {
129	            r.rank = 0;
130	        }
131	        let expected = reference_order(scrambled);
132	        prop_assert_eq!(ranked.iter().map(full_key).collect::<Vec<_>>(), expected.iter().map(full_key).collect::<Vec<_>>());
133	    }
134	
135	    #[test]
136	    fn rank_blocks_ignores_input_order_when_no_blocks_tie(
137	        blocks in prop::collection::vec(input_block(), 0..12),
138	        terms in terms_strategy(),
139	        df in df_strategy(),
140	        seed in any::<u64>(),
141	    ) {
142	        let key = |b: &CodeBlock| (b.file.clone(), b.line_start, b.line_end, KINDS.iter().position(|k| *k == b.node_kind), b.code.clone());
143	        let mut keys: Vec<_> = blocks.iter().map(|(b, _)| key(b)).collect();
144	        keys.sort();
145	        keys.dedup();
146	        prop_assume!(keys.len() == blocks.len());
147	
148	        let mut shuffled = blocks.clone();
149	        // Deterministic Fisher-Yates driven by a splitmix-style generator, so failures replay from the seed alone.
150	        let mut state = seed;
151	        for idx in (1..shuffled.len()).rev() {
152	            state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
153	            let mut z = state;
154	            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
155	            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
156	            let pick = usize::try_from((z ^ (z >> 31)) % (idx as u64 + 1)).unwrap_or(0);
157	            shuffled.swap(idx, pick);
158	        }
159	
160	        let original = rank_blocks(blocks, &terms, &df);
161	        let permuted = rank_blocks(shuffled, &terms, &df);
162	        prop_assert_eq!(original.iter().map(full_key).collect::<Vec<_>>(), permuted.iter().map(full_key).collect::<Vec<_>>());
163	    }
164	}
